statement:
Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

statement_tex:
\label{lemma-glue}
\begin{slogan}
If you have two locally ringed spaces, and a subspace of the first one
is isomorphic to a subspace of the other, then you can glue them together
into one big locally ringed space.
\end{slogan}
Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

\label{lemma-finite-jacobson}
A finite Jacobson space is discrete.
A Jacobson space with finitely many closed points is discrete.

\label{lemma-spec-spectral}
The spectrum of a ring is a spectral space, see Topology, Definition
\ref{topology-definition-spectral-space}.

\label{lemma-glueing-near-closed-point-modules}
Let $S$ be a scheme. Let $s \in S$ be a closed point such that
$U = S \setminus \{s\} \to S$ is quasi-compact. With
$V = \Spec(\mathcal{O}_{S, s}) \setminus \{s\}$ there is
an equivalence of categories
$$
\left\{
\mathcal{O}_S\text{-modules }\mathcal{F}\text{ of finite presentation}
\right\}
\longrightarrow
\left\{
(\mathcal{G}, \mathcal{H}, \alpha)
\right\}
$$
where on the right hand side we consider triples
consisting of a $\mathcal{O}_U$-module $\mathcal{G}$ of
finite presentation, a $\mathcal{O}_{\Spec(\mathcal{O}_{S, s})}$-module
$\mathcal{H}$ of finite presentation, and an isomorphism
$\alpha : \mathcal{G}|_V \to \mathcal{H}|_V$ of
$\mathcal{O}_V$-modules.

\label{lemma-contained-in-radical}
Let $R$ be a ring with Jacobson radical $\text{rad}(R)$.
Let $I \subset R$ be an ideal. The following are
equivalent
\begin{enumerate}
\item $I \subset \text{rad}(R)$, and
\item every element of $1 + I$ is a unit in $R$.
\end{enumerate}
In this case every element of $R$ which maps to a unit of $R/I$ is a unit.

\label{proposition-localize-twice-module}
View $S'^{-1}M$ as an $A$-module, then $S^{-1}(S'^{-1}M)$ is
isomorphic to $(SS')^{-1}M$.

\label{lemma-affine-separated}
An affine scheme is separated. A morphism from an affine scheme
to another scheme is separated.

\label{lemma-pid-jacobson}
The ring $\mathbf{Z}$ is a Jacobson ring.
More generally, let $R$ be a ring such that
\begin{enumerate}
\item $R$ is a domain,
\item $R$ is Noetherian,
\item any nonzero prime ideal is a maximal ideal, and
\item $R$ has infinitely many maximal ideals.
\end{enumerate}
Then $R$ is a Jacobson ring.

\label{lemma-relatively-prime-polynomials}
Two polynomials in $k[x]$ are relatively prime precisely when they
have no common roots in an algebraic closure $\overline{k}$ of $k$.

\label{lemma-unique-prime-over-localize-below}
Let $R \to S$ be a ring map.
Let $\mathfrak p \subset R$ be a prime.
Assume that
\begin{enumerate}
\item there exists a unique prime $\mathfrak q \subset S$ lying over
$\mathfrak p$, and
\item either
\begin{enumerate}
\item going up holds for $R \to S$, or
\item going down holds for $R \to S$ and there is at most one prime
of $S$ above every prime of $R$.
\end{enumerate}
\end{enumerate}
Then $S_{\mathfrak p} = S_{\mathfrak q}$.

